const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const calendarId = source.calendarId || payload.calendarId || 'primary';
const now = new Date();
const start = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}T00:00:00+07:00`;
const end = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}T23:59:59+07:00`;
return [{ json: { ...source, payload, message, chatId, calendarId, after: start, before: end, heading: 'Lịch hôm nay' } }];

const source = $('Chuan Bi Lich Hom Nay').item.json;
const rows = $input.all().map(item => item.json || {}).filter((event) => event && Object.keys(event).length > 0 && (event.id || event.summary || event.start || event.end));
let text = `📅 <b>${source.heading}</b>\n\n`;
if (rows.length === 0) {
  text += 'Không có lịch nào trong hôm nay.';
} else {
  for (let i = 0; i < rows.length; i++) {
    const event = rows[i];
    const title = event.summary || 'Không có tiêu đề';
    const start = event.start?.dateTime || event.start?.date || '';
    const end = event.end?.dateTime || event.end?.date || '';
    text += `<b>${i + 1}. ${title}</b>\n🕒 ${start}`;
    if (end) text += ` → ${end}`;
    text += '\n\n';
  }
}
return [{ json: { chatId: source.chatId, text: text.trim() } }];
